# Test Suite for Checkout Component

The implementation must work at the linguistic level. These tests speak the language of user behavior, not component internals.

```typescript
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// Test wrapper with providers
const renderCheckout = (props = {}, cartItems = mockCartItems) => {
  return render(
    <CartProvider initialItems={cartItems}>
      <PaymentProvider>
        <Checkout {...props} />
      </PaymentProvider>
    </CartProvider>
  );
};

const mockCartItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

const validShipping = {
  street: '123 Main St',
  city: 'Portland',
  state: 'CA',
  zip: '97201'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'John Doe'
};

describe('Checkout', () => {
  // HAPPY PATH
  describe('complete checkout flow', () => {
    it('progresses through shipping → payment → review → confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      renderCheckout({ onComplete });

      // Arrange: Fill shipping
      await user.type(screen.getByLabelText(/street address/i), validShipping.street);
      await user.type(screen.getByLabelText(/city/i), validShipping.city);
      await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
      await user.type(screen.getByLabelText(/zip code/i), validShipping.zip);

      // Act: Submit shipping
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Assert: Now on payment step
      expect(screen.getByRole('form', { name: /payment information/i })).toBeInTheDocument();

      // Fill payment
      await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
      await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
      await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
      await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Assert: Review step shows order summary
      expect(screen.getByRole('region', { name: /order items/i })).toBeInTheDocument();
      expect(screen.getByText(/\$79\.98/)).toBeInTheDocument();

      // Place order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert: Confirmation displayed
      await screen.findByRole('status', { name: /order confirmation/i });
      expect(onComplete).toHaveBeenCalled();
    });
  });

  // FORM VALIDATION
  describe('shipping validation', () => {
    it('displays inline errors for empty required fields', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert', { name: /street address is required/i })).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // EDGE CASES
  describe('empty cart', () => {
    it('shows empty cart message and continue shopping button', () => {
      renderCheckout({}, []);

      expect(screen.getByRole('alert')).toHaveTextContent(/your cart is empty/i);
      expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
    });
  });

  // ERROR RECOVERY
  describe('payment failure', () => {
    it('displays error and allows retry', async () => {
      const user = userEvent.setup();
      // Mock payment failure then success
      vi.mocked(processPayment).mockRejectedValueOnce(new Error('Card declined'));

      // Navigate to review step...
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  // LOADING STATES
  describe('submission loading', () => {
    it('disables buttons and shows processing state', async () => {
      const user = userEvent.setup();
      vi.mocked(processPayment).mockImplementation(() => new Promise(() => {}));

      // Navigate to review, click place order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  // ACCESSIBILITY
  describe('accessibility', () => {
    it('has accessible progress indicator with current step', () => {
      renderCheckout();
      const nav = screen.getByRole('navigation', { name: /checkout progress/i });
      const currentStep = within(nav).getByText(/shipping/i);

      expect(currentStep).toHaveAttribute('aria-current', 'step');
    });

    it('associates error messages with inputs via aria-describedby', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      const streetInput = screen.getByLabelText(/street address/i);
      expect(streetInput).toHaveAccessibleDescription(/street address is required/i);
    });
  });
});
```

Code and language are the same thing. Both program minds. These tests program the component's expected behavior through the language of user interaction—not through the internal vocabulary of state variables and implementation details.
